import type { AppSettings, CompanySettings, Customer, DocumentKind, EncryptedVaultRecord, ExpenseRecord, InventoryMovementRecord, LourexDocument, PaymentRecord, PurchaseRecord, SavedItem, Supplier, UiLanguage, VaultPayload } from '../types.js';
import { customerSnapshotFrom, defaultCompany, emptyVault } from '../lib/defaults.js';
import { createBlankDocument, convertToInvoice, duplicateDocument, nextCreditNoteNumber, nextDocumentNumber, validateDocument } from '../lib/documents.js';
import { assertDocumentLifecycleInvariant, auditedDocument, beginRevisionDraft, createCreditNoteDraft, createDocumentEvent, createRevisionRecord, invoiceCreditCapacity, restoreRevisionSnapshot, voidFinalDocument } from '../lib/document-lifecycle.js';
import { assertInvoicePaymentInvariant, normalizePaymentRecord } from '../lib/payments.js';
import { applyCustomerCommercialDefaults, applyPaymentTermPreset, assertCustomerCreditLimit, paymentTermPresetById, paymentTermPresetByLabel } from '../lib/commercial-controls.js';
import { inventoryMovementIsManual, postPurchase, reverseManualInventoryMovement, reversePurchase, validateExpense, validatePurchase, validateSupplier } from '../lib/operations.js';
import { findSavedItemDuplicate, findSavedItemMatch, markSavedItemsUsed, normalizeSavedItemIdentity, savedItemFromDocumentItem } from '../lib/saved-items.js';
import { exportBackup, readBackup } from '../lib/backup.js';
import { safeFilename } from '../lib/id.js';
import { getCloudAccount, getEncryptedVault, getPublicPreferences, getSecurity, hasSecurity, putCloudAccount, putPublicPreferences } from '../storage/db.js';
import { changePin, restoreVaultWithCurrentKey, resumeVaultSession, saveVault, setupVault, unlockVault } from '../storage/vault.js';
import { mergeVaultIntent } from '../storage/vault-merge.js';
import { clearSession, establishSession, isCurrentSessionExpired, touchSession } from '../storage/session.js';
import { verifyPin } from '../crypto/crypto.js';
import { setUiLanguage, t } from '../lib/i18n.js';
import { AuthScreenSelector } from './AuthScreenSelector.js';
import { DocumentsPage } from '../components/DocumentsPage.js';
import { CustomersPage } from '../components/CustomersPage.js';
import { ReceivablesPage } from '../components/ReceivablesPage.js';
import { ReportsPage } from '../components/ReportsPage.js';
import { OperationsPage } from '../components/OperationsPage.js';
import { SavedItemsPage } from '../components/SavedItemsPage.js';
import { EditorPage } from '../components/EditorPage.js';
import { SettingsModal } from '../components/SettingsModal.js';
import { CloudAccountModal } from '../components/CloudAccountModal.js';
import { Brand, Button, ConfirmDialog, Icon, IconButton, Toast } from '../components/UI.js';
import { TemplateRenderer } from '../templates/TemplateRenderer.js';
import { createCloudUser, friendlyCloudError, getCloudVaultMeta, pushLocalVaultToCloud, reconcileCloudVault, sendCloudPasswordReset, signInCloudUser, signOutCloudUser, waitForCloudUser } from '../cloud/firebase.js';
import type { CloudUser } from '../cloud/firebase.js';

type CloudSyncState='local'|'queued'|'syncing'|'synced'|'offline'|'error';

interface State {
  loading:boolean; firstRun:boolean; unlocked:boolean; key:CryptoKey|null; vault:VaultPayload|null;
  screen:'documents'|'customers'|'receivables'|'reports'|'items'|'operations'|'editor'; editorDoc:LourexDocument|null; settingsOpen:boolean; newMenu:boolean;
  deletingDoc:LourexDocument|null; toast:string; toastTone:'default'|'success'|'error'; printDoc:LourexDocument|null;
  publicLogo:string; uiLanguage:UiLanguage;
  cloudUser:CloudUser|null; cloudLinked:boolean; cloudModal:boolean; cloudSyncState:CloudSyncState; cloudSyncMessage:string;
}

export class App extends React.Component<{},State> {
  state:State={loading:true,firstRun:false,unlocked:false,key:null,vault:null,screen:'documents',editorDoc:null,settingsOpen:false,newMenu:false,deletingDoc:null,toast:'',toastTone:'default',printDoc:null,publicLogo:'./brand/lourex-logo.svg',uiLanguage:'en',cloudUser:null,cloudLinked:false,cloudModal:false,cloudSyncState:'local',cloudSyncMessage:''};
  private lockTimer:number|undefined;
  private toastTimer:number|undefined;
  private cloudTimer:number|undefined;
  private cloudSyncRunning=false;
  private cloudSyncQueued=false;
  private cloudRetryDelay=5_000;
  private lastCloudSyncedAt='';
  private lastActivityTouch=0;
  private latestEncryptedVault:EncryptedVaultRecord|null=null;
  private vaultWriteTail:Promise<VaultPayload|null>=Promise.resolve(null);
  private vaultReplacing=false;

  componentDidMount():void{
    void this.initialize();
    ['pointerdown','keydown','touchstart'].forEach(ev=>window.addEventListener(ev,this.activity,{passive:true}));
    document.addEventListener('visibilitychange',this.handleVisibilityChange);
    document.addEventListener('pointerdown',this.closeTransientMenus);
    window.addEventListener('afterprint',this.afterPrint);
    window.addEventListener('online',this.handleOnline);
    window.addEventListener('lourex-cloud-remote-newer',this.handleRemoteCloudNewer);
  }
  componentWillUnmount():void{
    ['pointerdown','keydown','touchstart'].forEach(ev=>window.removeEventListener(ev,this.activity));
    document.removeEventListener('visibilitychange',this.handleVisibilityChange);
    document.removeEventListener('pointerdown',this.closeTransientMenus);
    window.removeEventListener('afterprint',this.afterPrint);
    window.removeEventListener('online',this.handleOnline);
    window.removeEventListener('lourex-cloud-remote-newer',this.handleRemoteCloudNewer);
    if(this.lockTimer)clearTimeout(this.lockTimer);
    if(this.toastTimer)clearTimeout(this.toastTimer);
    if(this.cloudTimer)clearTimeout(this.cloudTimer);
  }

  private initialize=async()=>{
    try{
      let configured=await hasSecurity();
      const preferences=await getPublicPreferences();
      let uiLanguage=preferences?.uiLanguage??'en';
      let publicLogo=preferences?.logoDataUrl||'./brand/lourex-logo.svg';
      if(configured){
        const resumed=await resumeVaultSession();
        if(resumed){
          const vault={...resumed.vault,appSettings:{...resumed.vault.appSettings,uiLanguage:resumed.vault.appSettings.uiLanguage??uiLanguage}};
          uiLanguage=vault.appSettings.uiLanguage;publicLogo=vault.company.logoDataUrl||publicLogo;setUiLanguage(uiLanguage);
          this.vaultWriteTail=Promise.resolve(vault);
          this.setState({loading:false,firstRun:false,unlocked:true,key:resumed.key,vault,screen:'documents',editorDoc:null,uiLanguage,publicLogo,cloudUser:null,cloudLinked:false,cloudSyncState:'local',cloudSyncMessage:''},()=>{this.resetAutoLock();void this.initializeConfiguredCloud();});
          return;
        }
        setUiLanguage(uiLanguage);
        this.setState({loading:false,firstRun:false,unlocked:false,key:null,vault:null,uiLanguage,publicLogo,cloudUser:null,cloudLinked:false,cloudSyncState:'local',cloudSyncMessage:''},()=>void this.initializeConfiguredCloud());
        return;
      }
      let cloudUser:CloudUser|null=null;
      let cloudLinked=false;
      let cloudSyncState:CloudSyncState='local';
      let cloudSyncMessage='';
      try{cloudUser=await waitForCloudUser();}catch{}
      if(cloudUser){
        try{
          let linked=await getCloudAccount();
          if(linked&&linked.uid!==cloudUser.uid){cloudSyncState='error';cloudSyncMessage=t('This device is linked to a different LOUREX cloud account.','هذا الجهاز مرتبط بحساب LOUREX سحابي مختلف.');}
          else{
            if(!linked){await putCloudAccount(cloudUser.uid,cloudUser.email);linked=await getCloudAccount();}
            cloudLinked=Boolean(linked?.uid===cloudUser.uid);
            if(cloudLinked){
              const result=await reconcileCloudVault(cloudUser.uid);
              if(result==='pulled'){configured=true;await clearSession();}
              if(result!=='empty'){cloudSyncState='synced';cloudSyncMessage=t('Encrypted cloud data restored.','تمت استعادة البيانات السحابية المشفّرة.');}
            }
          }
        }catch(e){cloudSyncState='error';cloudSyncMessage=friendlyCloudError(e);}
      }
      setUiLanguage(uiLanguage);
      this.setState({loading:false,firstRun:!configured,unlocked:false,key:null,vault:null,uiLanguage,publicLogo,cloudUser,cloudLinked,cloudSyncState,cloudSyncMessage});
    }catch(e){this.setState({loading:false,cloudSyncState:'error',cloudSyncMessage:friendlyCloudError(e)});this.showToast(e instanceof Error?e.message:t('Unable to access local storage.','تعذر الوصول إلى التخزين المحلي.'),'error');}
  };

  private initializeConfiguredCloud=async()=>{
    let cloudUser:CloudUser|null=null;
    try{cloudUser=await waitForCloudUser();}catch{}
    if(!cloudUser){this.setState({cloudUser:null,cloudLinked:false,cloudSyncState:'local',cloudSyncMessage:''});return;}
    try{
      const linked=await getCloudAccount();
      if(linked&&linked.uid!==cloudUser.uid){this.setState({cloudUser,cloudLinked:false,cloudSyncState:'error',cloudSyncMessage:t('This device is linked to a different LOUREX cloud account.','هذا الجهاز مرتبط بحساب LOUREX سحابي مختلف.')});return;}
      if(!linked){
        const remote=await getCloudVaultMeta(cloudUser.uid);
        if(remote){this.setState({cloudUser,cloudLinked:false,cloudSyncState:'error',cloudSyncMessage:t('This cloud account already contains LOUREX data. Sign in with the account originally linked to this device or use Sync Now from the correct device.','هذا الحساب السحابي يحتوي بالفعل على بيانات LOUREX. سجّل بالحساب المرتبط أصلًا بهذا الجهاز أو استخدم المزامنة من الجهاز الصحيح.')});return;}
        await putCloudAccount(cloudUser.uid,cloudUser.email);
      }
      this.setState({cloudUser,cloudLinked:true,cloudSyncState:'local',cloudSyncMessage:t('Cloud account connected.','الحساب السحابي متصل.')},()=>{
        if(this.state.screen==='editor'||this.state.settingsOpen||this.state.cloudModal)return;
        void this.cloudSyncNow().catch(()=>undefined);
      });
    }catch(e){this.setState({cloudUser,cloudLinked:false,cloudSyncState:'error',cloudSyncMessage:friendlyCloudError(e)});}
  };

  private activity=()=>{
    if(!this.state.unlocked)return;
    const now=Date.now();
    // localStorage writes and timeout churn on every editor keystroke made typing
    // visibly heavier on iPhone. A 15s activity heartbeat preserves auto-lock
    // accuracy while keeping the hot input path synchronous-work free.
    if(now-this.lastActivityTouch<15_000)return;
    this.lastActivityTouch=now;
    touchSession(now);
    this.resetAutoLock();
  };
  private handleOnline=()=>{this.scheduleCloudSync(500);};
  private handleRemoteCloudNewer=()=>{if(!this.state.cloudUser||!this.state.cloudLinked||this.state.screen==='editor'||this.state.settingsOpen||this.state.cloudModal||this.vaultReplacing)return;void this.cloudSyncNow().catch(()=>undefined);};
  private handleVisibilityChange=()=>{if(document.visibilityState!=='visible'||!this.state.unlocked)return;const mins=this.state.vault?.appSettings.autoLockMinutes??15;if(isCurrentSessionExpired(mins)){void this.lockNow(true);return;}touchSession();this.resetAutoLock();this.scheduleCloudSync(700);};
  private closeTransientMenus=(event:PointerEvent)=>{if(!this.state.newMenu)return;const target=event.target;if(target instanceof Element&&target.closest('.new-doc-menu'))return;this.setState({newMenu:false});};
  private resetAutoLock=()=>{if(this.lockTimer)window.clearTimeout(this.lockTimer);const mins=this.state.vault?.appSettings.autoLockMinutes??15;if(mins>0)this.lockTimer=window.setTimeout(()=>void this.lockNow(true),mins*60_000);};
  private showToast=(toast:string,tone:'default'|'success'|'error'='default')=>{if(this.toastTimer)clearTimeout(this.toastTimer);this.setState({toast,toastTone:tone});this.toastTimer=window.setTimeout(()=>this.setState({toast:''}),3600);};
  private normalizedVault=(vault:VaultPayload):VaultPayload=>({...vault,appSettings:{...vault.appSettings,uiLanguage:vault.appSettings.uiLanguage??this.state.uiLanguage??'en'}});
  private syncPublicPreferences=async(logoDataUrl:string,uiLanguage:UiLanguage)=>{const publicLogo=logoDataUrl||'./brand/lourex-logo.svg';setUiLanguage(uiLanguage);this.setState({publicLogo,uiLanguage});try{await putPublicPreferences({logoDataUrl:publicLogo,uiLanguage});}catch{}};
  private changePublicLanguage=async(uiLanguage:UiLanguage)=>{await this.syncPublicPreferences(this.state.publicLogo||'./brand/lourex-logo.svg',uiLanguage);};
  private drainVaultWrites=async()=>{try{await this.vaultWriteTail;}catch{}};
  private waitForCloudIdle=async()=>{while(this.cloudSyncRunning)await new Promise(resolve=>window.setTimeout(resolve,30));};
  private waitForProtectedDataOperation=async()=>{const deadline=Date.now()+30_000;while(this.vaultReplacing){if(!this.state.unlocked||!this.state.key)throw new Error(t('App is locked.','التطبيق مقفل.'));if(Date.now()>=deadline)throw new Error(t('Cloud restore is still finishing. Try again in a moment.','ما زالت استعادة البيانات السحابية قيد الإنهاء. حاول مرة أخرى بعد لحظة.'));await new Promise(resolve=>window.setTimeout(resolve,50));}};
  private editorMustBeClosed=(actionEn:string,actionAr:string)=>{if(this.state.screen!=='editor')return;throw new Error(t(`Close the document editor before ${actionEn}.`,`أغلق محرر المستند قبل ${actionAr}.`));};
  private beginProtectedOperation=async()=>{if(this.cloudTimer){window.clearTimeout(this.cloudTimer);this.cloudTimer=undefined;}await this.drainVaultWrites();await this.waitForCloudIdle();this.latestEncryptedVault=null;this.vaultReplacing=true;};
  private endProtectedOperation=()=>{this.vaultReplacing=false;};

  private scheduleCloudSync=(delay=1_200)=>{
    if(!this.state.cloudUser||!this.state.cloudLinked)return;
    if(this.cloudTimer)window.clearTimeout(this.cloudTimer);
    const offline=typeof navigator!=='undefined'&&!navigator.onLine;
    this.setState({
      cloudSyncState:offline?'offline':'queued',
      cloudSyncMessage:offline
        ?t('Offline — saved locally. Cloud sync will resume automatically.','غير متصل — تم الحفظ محليًا وستُستأنف المزامنة تلقائيًا.')
        :t('Saved locally — cloud sync queued.','تم الحفظ محليًا — المزامنة السحابية في الانتظار.')
    });
    this.cloudTimer=window.setTimeout(()=>void this.flushCloudSync(),offline?this.cloudRetryDelay:delay);
  };
  private flushCloudSync=async()=>{
    this.cloudTimer=undefined;
    const user=this.state.cloudUser;
    if(!user||!this.state.cloudLinked)return;
    if(this.vaultReplacing||this.cloudSyncRunning){this.cloudSyncQueued=true;return;}
    if(typeof navigator!=='undefined'&&!navigator.onLine){
      this.setState({cloudSyncState:'offline',cloudSyncMessage:t('Offline — saved locally. Cloud sync will resume automatically.','غير متصل — تم الحفظ محليًا وستُستأنف المزامنة تلقائيًا.')});
      return;
    }
    await this.drainVaultWrites();
    if(this.vaultReplacing){this.cloudSyncQueued=true;return;}
    const [linked,storedLocal]=await Promise.all([getCloudAccount(),this.latestEncryptedVault?Promise.resolve(this.latestEncryptedVault):getEncryptedVault()]);
    const local=storedLocal;
    if(!linked||linked.uid!==user.uid||!local)return;
    if(local.updatedAt===this.lastCloudSyncedAt){
      this.setState({cloudSyncState:'synced',cloudSyncMessage:t('Cloud is up to date.','السحابة محدثة.')});
      return;
    }
    this.cloudSyncRunning=true;
    this.setState({cloudSyncState:'syncing',cloudSyncMessage:t('Syncing in background…','جارٍ المزامنة في الخلفية…')});
    try{
      await pushLocalVaultToCloud(user.uid,local);
      this.lastCloudSyncedAt=local.updatedAt;
      this.cloudRetryDelay=5_000;
      const newest=this.latestEncryptedVault??await getEncryptedVault();
      if(newest&&newest.updatedAt!==local.updatedAt){
        this.cloudSyncQueued=true;
        this.setState({cloudSyncState:'queued',cloudSyncMessage:t('Newer local changes are waiting to sync.','توجد تعديلات محلية أحدث بانتظار المزامنة.')});
      }else this.setState({cloudSyncState:'synced',cloudSyncMessage:t('Cloud is up to date.','السحابة محدثة.')});
    }catch(e){
      const retryDelay=this.cloudRetryDelay;
      this.cloudRetryDelay=Math.min(60_000,this.cloudRetryDelay*2);
      this.setState({cloudSyncState:'error',cloudSyncMessage:t(`${friendlyCloudError(e)} Retry scheduled.`,`${friendlyCloudError(e)} ستتم إعادة المحاولة تلقائيًا.`)});
      if(!this.cloudTimer)this.cloudTimer=window.setTimeout(()=>void this.flushCloudSync(),retryDelay);
    }finally{
      this.cloudSyncRunning=false;
      if(this.cloudSyncQueued){this.cloudSyncQueued=false;this.scheduleCloudSync(700);}
    }
  };
  private attachCloudUser=async(user:CloudUser)=>{const [linked,configured]=await Promise.all([getCloudAccount(),hasSecurity()]);if(linked&&linked.uid!==user.uid){await signOutCloudUser();this.setState({cloudUser:null,cloudLinked:false});throw new Error(t('This device is already linked to another LOUREX cloud account.','هذا الجهاز مرتبط مسبقًا بحساب LOUREX سحابي آخر.'));}if(!linked&&configured){const remote=await getCloudVaultMeta(user.uid);if(remote){await signOutCloudUser();this.setState({cloudUser:null,cloudLinked:false});throw new Error(t('This cloud account already contains LOUREX data. Use an empty device to restore it, or sign in with the account originally linked to this device.','هذا الحساب السحابي يحتوي بالفعل على بيانات LOUREX. استخدم جهازًا فارغًا لاستعادتها أو سجّل بالحساب المرتبط أصلًا بهذا الجهاز.'));}}await putCloudAccount(user.uid,user.email);this.setState({cloudUser:user,cloudLinked:true,cloudSyncState:'syncing',cloudSyncMessage:t('Connecting encrypted cloud backup…','جارٍ ربط النسخة السحابية المشفّرة…')});try{const result=await reconcileCloudVault(user.uid);if(result==='pulled'){await clearSession();this.setState({cloudSyncState:'synced',cloudSyncMessage:t('Cloud data restored. Enter your LOUREX PIN to unlock it.','تمت استعادة البيانات السحابية. أدخل رمز PIN الخاص بـ LOUREX لفتحها.')});window.location.reload();return;}this.setState({cloudSyncState:result==='empty'?'local':'synced',cloudSyncMessage:result==='empty'?t('Cloud account linked. Finish local setup to create the first encrypted sync.','تم ربط الحساب السحابي. أكمل الإعداد المحلي لإنشاء أول مزامنة مشفّرة.'):t('Encrypted cloud data is up to date.','البيانات السحابية المشفّرة محدثة.')});}catch(e){this.setState({cloudSyncState:'error',cloudSyncMessage:friendlyCloudError(e)});}};
  private cloudSignIn=async(email:string,password:string)=>{try{const user=await signInCloudUser(email,password);this.setState({cloudUser:user});await this.attachCloudUser(user);}catch(e){throw new Error(friendlyCloudError(e));}};
  private cloudCreate=async(email:string,password:string)=>{try{const user=await createCloudUser(email,password);this.setState({cloudUser:user});await this.attachCloudUser(user);}catch(e){throw new Error(friendlyCloudError(e));}};
  private cloudReset=async(email:string)=>{try{await sendCloudPasswordReset(email);}catch(e){throw new Error(friendlyCloudError(e));}};
  private cloudSignOut=async()=>{await signOutCloudUser();this.setState({cloudUser:null,cloudLinked:false,cloudSyncState:'local',cloudSyncMessage:t('Signed out of cloud. Local encrypted data remains on this device.','تم تسجيل الخروج من السحابة. تبقى البيانات المحلية المشفّرة على هذا الجهاز.')});};
  private cloudSyncNow=async()=>{
    this.editorMustBeClosed('syncing from the cloud','المزامنة من السحابة');
    if(this.cloudTimer){window.clearTimeout(this.cloudTimer);this.cloudTimer=undefined;}
    await this.drainVaultWrites();await this.waitForCloudIdle();
    try{
      const user=this.state.cloudUser;if(!user)throw new Error(t('Sign in to LOUREX Cloud first.','سجّل الدخول إلى سحابة LOUREX أولًا.'));
      const linked=await getCloudAccount();if(!linked){await this.attachCloudUser(user);return;}if(linked.uid!==user.uid)throw new Error(t('This device is linked to another cloud account.','هذا الجهاز مرتبط بحساب سحابي آخر.'));
      this.setState({cloudSyncState:'syncing',cloudSyncMessage:t('Checking encrypted cloud data…','جارٍ فحص البيانات السحابية المشفّرة…')});
      const [local,remote]=await Promise.all([getEncryptedVault(),getCloudVaultMeta(user.uid)]);
      const remoteMustReplaceLocal=Boolean(remote&&(!local||remote.updatedAt>local.updatedAt));
      if(remoteMustReplaceLocal){
        if((this.state.screen as State['screen'])==='editor'||this.state.settingsOpen){this.setState({cloudSyncState:'local',cloudSyncMessage:t('Newer cloud data is waiting. Close the editor or settings, then use Sync Now.','توجد بيانات سحابية أحدث بانتظار الاستعادة. أغلق المحرر أو الإعدادات ثم استخدم «مزامنة الآن».')});return;}
        await this.beginProtectedOperation();
        try{
          if((this.state.screen as State['screen'])==='editor'||this.state.settingsOpen){this.setState({cloudSyncState:'local',cloudSyncMessage:t('Newer cloud data is waiting. Close the editor or settings, then use Sync Now.','توجد بيانات سحابية أحدث بانتظار الاستعادة. أغلق المحرر أو الإعدادات ثم استخدم «مزامنة الآن».')});return;}
          const result=await reconcileCloudVault(user.uid);if(result==='pulled'){await clearSession();window.location.reload();return;}this.setState({cloudSyncState:'synced',cloudSyncMessage:t('Encrypted cloud data is up to date.','البيانات السحابية المشفّرة محدثة.')});
        }finally{this.endProtectedOperation();}
        return;
      }
      this.cloudSyncRunning=true;
      try{if(local){await pushLocalVaultToCloud(user.uid,local);this.lastCloudSyncedAt=local.updatedAt;}const newest=this.latestEncryptedVault??await getEncryptedVault();if(local&&newest&&newest.updatedAt!==local.updatedAt){this.cloudSyncQueued=true;this.setState({cloudSyncState:'queued',cloudSyncMessage:t('Newer local changes are waiting to sync.','توجد تعديلات محلية أحدث بانتظار المزامنة.')});}else this.setState({cloudSyncState:'synced',cloudSyncMessage:t('Encrypted cloud data is up to date.','البيانات السحابية المشفّرة محدثة.')});}
      finally{this.cloudSyncRunning=false;if(this.cloudSyncQueued){this.cloudSyncQueued=false;this.scheduleCloudSync(500);}}
    }catch(e){const message=friendlyCloudError(e);this.setState({cloudSyncState:'error',cloudSyncMessage:message});throw new Error(message);}
  };

  private finishSetup=async(pin:string,company:CompanySettings)=>{const base=emptyVault();const vault={...base,company,appSettings:{...base.appSettings,uiLanguage:this.state.uiLanguage,smartDefaults:{...base.appSettings.smartDefaults,currency:company.defaultCurrency||'USD',language:company.defaultLanguage,incoterm:company.defaultIncoterm,paymentTerms:company.defaultPaymentTerms,deliveryTime:company.defaultDeliveryTime}}};const setup=await setupVault(pin,vault);await establishSession(setup.key);await this.syncPublicPreferences(company.logoDataUrl,this.state.uiLanguage);let cloudLinked=this.state.cloudLinked,cloudSyncState=this.state.cloudSyncState,cloudSyncMessage=this.state.cloudSyncMessage;if(this.state.cloudUser){try{await putCloudAccount(this.state.cloudUser.uid,this.state.cloudUser.email);cloudLinked=true;cloudSyncState='queued';cloudSyncMessage=t('Setup saved locally — cloud backup queued.','تم حفظ الإعداد محليًا — النسخة السحابية في الانتظار.');}catch(e){cloudSyncState='error';cloudSyncMessage=friendlyCloudError(e);}}this.vaultWriteTail=Promise.resolve(setup.vault);this.setState({firstRun:false,unlocked:true,key:setup.key,vault:setup.vault,screen:'documents',cloudLinked,cloudSyncState,cloudSyncMessage},()=>{this.resetAutoLock();this.scheduleCloudSync(350);});this.showToast(t('LOUREX Invoice is ready.','نظام LOUREX Invoice جاهز.'),'success');};
  private unlock=async(pin:string)=>{const result=await unlockVault(pin);const needsMigration=!result.vault.appSettings.uiLanguage;const vault=this.normalizedVault(result.vault);if(needsMigration)await saveVault(result.key,vault);await establishSession(result.key);await this.syncPublicPreferences(vault.company.logoDataUrl,vault.appSettings.uiLanguage);this.vaultWriteTail=Promise.resolve(vault);this.setState({unlocked:true,key:result.key,vault,screen:'documents',editorDoc:null},()=>{this.resetAutoLock();if(this.state.cloudUser&&this.state.cloudLinked)void this.cloudSyncNow().catch(()=>undefined);else this.scheduleCloudSync(1200);});};
  private lock=()=>{void this.lockNow(false);};
  private lockNow=async(automatic:boolean)=>{if(!automatic&&this.state.screen==='editor'){this.showToast(t('Close the document editor before locking the app.','أغلق محرر المستند قبل قفل التطبيق.'),'error');return;}if(this.lockTimer)window.clearTimeout(this.lockTimer);await this.drainVaultWrites();await clearSession();this.latestEncryptedVault=null;this.vaultWriteTail=Promise.resolve(null);this.setState({unlocked:false,key:null,vault:null,editorDoc:null,screen:'documents',settingsOpen:false,newMenu:false});};
  private persist=async(intended:VaultPayload)=>{const base=this.requireVault();await this.waitForProtectedDataOperation();const operation=this.vaultWriteTail.catch(()=>null).then(async queued=>{await this.waitForProtectedDataOperation();const key=this.state.key;if(!key)throw new Error(t('App is locked.','التطبيق مقفل.'));const latest=queued??this.state.vault??base;const merged=mergeVaultIntent(base,intended,latest);const encrypted=await saveVault(key,merged);this.latestEncryptedVault=encrypted;if(this.state.unlocked&&this.state.key===key)await new Promise<void>(resolve=>this.setState({vault:merged},resolve));this.scheduleCloudSync();return merged;});this.vaultWriteTail=operation;await operation;};
  private reserveDocument=async(kind:DocumentKind):Promise<{doc:LourexDocument;vault:VaultPayload}>=>{const vault=this.requireVault();const next=nextDocumentNumber(vault,kind);await this.persist(next.vault);const current=this.requireVault();const smart=current.appSettings.smartDefaults;const base=createBlankDocument(kind,next.number,current.company);const paymentTerms=smart.paymentTerms||base.terms.paymentTerms;let doc={...base,currency:smart.currency||base.currency,language:smart.language||base.language,terms:{...base.terms,incoterm:smart.incoterm,paymentTerms,deliveryTime:smart.deliveryTime},appearance:{...base.appearance,templateId:kind==='proforma'?smart.quoteTemplateId:smart.invoiceTemplateId}};const paymentPreset=paymentTermPresetByLabel(current.company,paymentTerms);if(paymentPreset)doc=applyPaymentTermPreset(doc,paymentPreset);return{doc,vault:current};};
  private newDocument=async(kind:DocumentKind)=>{try{const {doc}=await this.reserveDocument(kind);this.setState({screen:'editor',editorDoc:doc,newMenu:false});}catch(e){this.showToast(e instanceof Error?e.message:t('Unable to create document.','تعذر إنشاء المستند.'),'error');}};
  private newDocumentForCustomer=async(kind:DocumentKind,customer:Customer)=>{try{const {doc}=await this.reserveDocument(kind);const prepared=applyCustomerCommercialDefaults({...doc,customerSnapshot:customerSnapshotFrom(customer)},customer,this.requireVault().company);await new Promise<void>(resolve=>this.setState({screen:'editor',editorDoc:prepared,newMenu:false},resolve));}catch(e){throw e instanceof Error?e:new Error(t('Unable to create document.','تعذر إنشاء المستند.'));}};
  private saveDocument=async(doc:LourexDocument,auto=false)=>{const vault=this.requireVault();if(vault.documents.some(d=>d.id!==doc.id&&d.number.trim().toLowerCase()===doc.number.trim().toLowerCase()))throw new Error(t('Document number already exists.','رقم المستند مستخدم بالفعل.'));const index=vault.documents.findIndex(d=>d.id===doc.id);const existing=index>=0?vault.documents[index]:undefined;if(existing?.lifecycleStatus==='voided')throw new Error(t('Voided documents are locked permanently.','المستندات الملغاة مقفلة بشكل دائم.'));const documents=[...vault.documents];const updated={...doc,role:doc.role||'standard',lifecycleStatus:doc.lifecycleStatus||'active',revision:Math.max(1,doc.revision||1),creditForId:doc.creditForId||'',creditForNumber:doc.creditForNumber||'',voidedAt:doc.voidedAt||'',voidReason:doc.voidReason||'',bankAccountId:doc.bankAccountId||'',paymentTermPresetId:doc.paymentTermPresetId||'',updatedAt:new Date().toISOString()};if(updated.status==='final'&&existing?.status!=='final')assertCustomerCreditLimit(updated,vault.customers,vault.documents,vault.payments);assertInvoicePaymentInvariant(updated,vault.payments,vault.documents);if(index>=0)documents[index]=updated;else documents.push(updated);assertDocumentLifecycleInvariant(updated,documents,vault.payments);let documentEvents=vault.documentEvents;if(!existing){documentEvents=[...documentEvents,createDocumentEvent(updated,'created')];if(updated.status==='final')documentEvents=[...documentEvents,createDocumentEvent(updated,updated.revision>1?'reissued':'issued')];}else if(existing.status==='draft'&&updated.status==='final')documentEvents=[...documentEvents,createDocumentEvent(updated,updated.revision>1?'reissued':'issued')];const appSettings=auto?vault.appSettings:{...vault.appSettings,smartDefaults:{...vault.appSettings.smartDefaults,currency:updated.currency,language:updated.language,incoterm:updated.terms.incoterm,paymentTerms:updated.terms.paymentTerms,deliveryTime:updated.terms.deliveryTime,[updated.kind==='proforma'?'quoteTemplateId':'invoiceTemplateId']:updated.appearance.templateId}};await this.persist({...vault,documents,documentEvents,appSettings});this.setState({editorDoc:updated});if(!auto)this.showToast(t('Document saved. Smart defaults updated.','تم حفظ المستند وتحديث الإعدادات الذكية.'),'success');};
  private beginRevision=async(source:LourexDocument):Promise<LourexDocument>=>{const vault=this.requireVault();const current=vault.documents.find(doc=>doc.id===source.id)??source;if(current.kind==='invoice'&&current.role==='standard'){const exposure=invoiceCreditCapacity(current,vault.documents,vault.payments);if(exposure.paid!=='0.00'||exposure.credited!=='0.00')throw new Error(t('An invoice with payments or issued credit notes cannot be revised. Use a credit note for financial corrections.','لا يمكن مراجعة فاتورة عليها دفعات أو إشعارات دائنة صادرة. استخدم إشعارًا دائنًا للتصحيح المالي.'));}const draft=beginRevisionDraft(current);const revision=createRevisionRecord(current);const documents=vault.documents.map(doc=>doc.id===current.id?draft:doc);const documentRevisions=[...vault.documentRevisions,revision];const documentEvents=[...vault.documentEvents,createDocumentEvent(current,'revision-started',t(`Revision ${draft.revision} started.`,`بدأت المراجعة ${draft.revision}.`))];await this.persist({...vault,documents,documentRevisions,documentEvents});this.setState({editorDoc:draft});return draft;};
  private discardRevision=async(source:LourexDocument)=>{const vault=this.requireVault();const restored=restoreRevisionSnapshot(source,vault.documentRevisions);const documents=vault.documents.map(doc=>doc.id===source.id?restored:doc);const documentEvents=[...vault.documentEvents,createDocumentEvent(restored,'revision-discarded',t(`Revision ${source.revision} discarded.`,`تم إلغاء المراجعة ${source.revision}.`))];await this.persist({...vault,documents,documentEvents});this.setState({editorDoc:restored});this.showToast(t('Revision discarded. Previous final restored.','تم إلغاء المراجعة واستعادة النسخة النهائية السابقة.'),'success');};
  private voidDocument=async(source:LourexDocument,reason:string)=>{const vault=this.requireVault();const current=vault.documents.find(doc=>doc.id===source.id)??source;const voided=voidFinalDocument(current,reason,vault.documents,vault.payments);const documents=vault.documents.map(doc=>doc.id===current.id?voided:doc);const documentEvents=[...vault.documentEvents,createDocumentEvent(voided,'voided',reason)];await this.persist({...vault,documents,documentEvents});this.setState({editorDoc:voided});this.showToast(current.kind==='proforma'?t('Quote cancelled.','تم إلغاء عرض السعر.'):t('Document voided.','تم إلغاء المستند.'),'success');};
  private createCreditNote=async(source:LourexDocument)=>{const vault=this.requireVault();const current=vault.documents.find(doc=>doc.id===source.id)??source;const capacity=invoiceCreditCapacity(current,vault.documents,vault.payments);if(capacity.available==='0.00')throw new Error(t('No remaining invoice balance is available to credit.','لا يوجد رصيد متبقٍ في الفاتورة لإصدار إشعار دائن.'));const numbered=nextCreditNoteNumber(vault);const credit=createCreditNoteDraft(current,numbered.number,capacity.available);const documents=[...numbered.vault.documents,credit];assertDocumentLifecycleInvariant(credit,documents,vault.payments);const documentEvents=[...vault.documentEvents,createDocumentEvent(current,'credit-note-created','',credit),createDocumentEvent(credit,'created','',current)];await this.persist({...numbered.vault,documents,documentEvents});this.setState({screen:'editor',editorDoc:credit});this.showToast(t(`Created ${credit.number}.`,`تم إنشاء ${credit.number}.`),'success');};
  private saveSmartDefaults=async(smartDefaults:AppSettings['smartDefaults'])=>{const vault=this.requireVault();await this.persist({...vault,appSettings:{...vault.appSettings,smartDefaults}});};
  private saveSavedItem=async(item:SavedItem)=>{const vault=this.requireVault();const current=vault.savedItems.find(existing=>existing.id===item.id);const identityChanged=!current||normalizeSavedItemIdentity(current.descriptionEn)!==normalizeSavedItemIdentity(item.descriptionEn)||normalizeSavedItemIdentity(current.descriptionAr)!==normalizeSavedItemIdentity(item.descriptionAr);const duplicate=identityChanged?findSavedItemDuplicate(vault.savedItems,item):undefined;if(duplicate)throw new Error(t('This item already exists. Open the existing item to edit it.','هذا الصنف موجود بالفعل. افتح الصنف الموجود لتعديله.'));const index=vault.savedItems.findIndex(x=>x.id===item.id);const savedItems=[...vault.savedItems];if(index>=0)savedItems[index]={...item,updatedAt:new Date().toISOString()};else savedItems.push(item);await this.persist({...vault,savedItems});this.showToast(t('Item saved to product library.','تم حفظ الصنف في مكتبة الأصناف.'),'success');};
  private saveSavedItemsBatch=async(items:SavedItem[])=>{if(!items.length)return;const vault=this.requireVault();const savedItems=[...vault.savedItems];const updatedAt=new Date().toISOString();for(const source of items){const item={...source,sku:(source.sku??'').trim().toUpperCase(),lastCurrency:(source.lastCurrency||vault.appSettings.smartDefaults.currency||'USD').trim().toUpperCase(),category:(source.category??'').trim(),tags:Array.from(new Set((source.tags??[]).map(tag=>tag.trim()).filter(Boolean))),favorite:Boolean(source.favorite),updatedAt};const duplicate=findSavedItemDuplicate(savedItems,item);if(duplicate)throw new Error(t(`Import conflict: ${item.sku||item.descriptionEn||item.descriptionAr} matches an existing product.`,`تعارض في الاستيراد: ${item.sku||item.descriptionEn||item.descriptionAr} يطابق صنفًا موجودًا.`));const index=savedItems.findIndex(existing=>existing.id===item.id);if(index>=0)savedItems[index]=item;else savedItems.push(item);}await this.persist({...vault,savedItems});this.showToast(t(`${items.length} products imported in one secure update.`,`تم استيراد ${items.length} صنف ضمن تحديث آمن واحد.`),'success');};
  private saveDocumentItem=async(item:LourexDocument['items'][number],currency:string)=>{const vault=this.requireVault();const existing=findSavedItemMatch(vault.savedItems,item);await this.saveSavedItem(savedItemFromDocumentItem(item,currency,existing));};
  private useSavedItems=async(items:SavedItem[])=>{const vault=this.requireVault();await this.persist({...vault,savedItems:markSavedItemsUsed(vault.savedItems,items)});};
  private deleteSavedItem=async(item:SavedItem)=>{const vault=this.requireVault();if(vault.inventoryMovements.some(movement=>movement.itemId===item.id)||vault.purchases.some(purchase=>purchase.items.some(line=>line.savedItemId===item.id)))throw new Error(t('This item has purchase or inventory history and cannot be deleted. Keep it for audit continuity.','لهذا الصنف سجل مشتريات أو مخزون ولا يمكن حذفه. احتفظ به لاستمرارية سجل التدقيق.'));await this.persist({...vault,savedItems:vault.savedItems.filter(x=>x.id!==item.id)});this.showToast(t('Saved item deleted.','تم حذف الصنف المحفوظ.'),'success');};
  private openDocument=async(doc:LourexDocument)=>{try{await this.waitForProtectedDataOperation();this.setState({screen:'editor',editorDoc:structuredClone(doc)});}catch(e){this.showToast(e instanceof Error?e.message:t('Unable to open document.','تعذر فتح المستند.'),'error');}};
  private duplicate=async(source:LourexDocument)=>{try{if(source.role==='credit-note')throw new Error(t('Create a new credit note from the source invoice instead of duplicating a credit note.','أنشئ إشعارًا دائنًا جديدًا من الفاتورة الأصلية بدل نسخ إشعار دائن.'));const {doc:blank}=await this.reserveDocument(source.kind);const vault=this.requireVault();const copy=duplicateDocument(source,blank.number);await this.persist({...vault,documents:[...vault.documents,copy]});this.setState({screen:'editor',editorDoc:copy});this.showToast(t('Duplicate created.','تم إنشاء نسخة.'),'success');}catch(e){this.showToast(e instanceof Error?e.message:t('Duplicate failed.','تعذر إنشاء نسخة.'),'error');}};
  private convert=async(source:LourexDocument)=>{try{const current=this.requireVault();if(source.lifecycleStatus==='voided')throw new Error(t('A cancelled quote cannot be converted to an invoice.','لا يمكن تحويل عرض سعر ملغى إلى فاتورة.'));const errors=validateDocument(source);if(Object.keys(errors).length)throw new Error(t('Save a valid Proforma before converting it.','احفظ عرض سعر صالحًا قبل تحويله.'));if(current.documents.some(d=>d.id!==source.id&&d.number.trim().toLowerCase()===source.number.trim().toLowerCase()))throw new Error(t('Document number already exists.','رقم المستند مستخدم بالفعل.'));const savedSource={...source,updatedAt:new Date().toISOString()};const sourceIndex=current.documents.findIndex(d=>d.id===source.id);const sourceDocuments=[...current.documents];if(sourceIndex>=0)sourceDocuments[sourceIndex]=savedSource;else sourceDocuments.push(savedSource);const withSource={...current,documents:sourceDocuments};const numbered=nextDocumentNumber(withSource,'invoice');let converted=convertToInvoice(savedSource,numbered.number);const convertedPaymentPreset=paymentTermPresetById(current.company,converted.paymentTermPresetId)||paymentTermPresetByLabel(current.company,converted.terms.paymentTerms);if(convertedPaymentPreset)converted=applyPaymentTermPreset(converted,convertedPaymentPreset);const convertedDocuments=[...sourceDocuments,converted];const documentEvents=[...current.documentEvents,createDocumentEvent(savedSource,'converted','',converted),createDocumentEvent(converted,'created','',savedSource)];await this.persist({...numbered.vault,documents:convertedDocuments,documentEvents});this.setState({screen:'editor',editorDoc:converted});this.showToast(t(`Created ${converted.number}.`,`تم إنشاء ${converted.number}.`),'success');}catch(e){this.showToast(e instanceof Error?e.message:t('Conversion failed.','فشل التحويل.'),'error');}};
  private deleteDocument=async()=>{const target=this.state.deletingDoc;if(!target)return;try{const vault=this.requireVault();if(target.status==='draft'&&target.revision>1)throw new Error(t('Discard the revision from Document History instead of deleting it.','ألغِ المراجعة من سجل المستند بدل حذفها.'));if(auditedDocument(vault,target))throw new Error(t('Issued or audited documents cannot be deleted. Void or cancel them to preserve history.','لا يمكن حذف المستندات الصادرة أو التي لها سجل. استخدم الإلغاء للحفاظ على التاريخ.'));if(vault.payments.some(payment=>payment.invoiceId===target.id))throw new Error(t('Delete the invoice payments before deleting this invoice.','احذف دفعات الفاتورة قبل حذف الفاتورة.'));await this.persist({...vault,documents:vault.documents.filter(d=>d.id!==target.id)});this.setState({deletingDoc:null});this.showToast(t('Draft deleted.','تم حذف المسودة.'),'success');}catch(e){this.showToast(e instanceof Error?e.message:t('Delete failed.','فشل الحذف.'),'error');}};
  private savePayment=async(payment:PaymentRecord)=>{const vault=this.requireVault();const invoice=vault.documents.find(document=>document.id===payment.invoiceId);if(!invoice)throw new Error(t('Invoice not found.','الفاتورة غير موجودة.'));const normalized=normalizePaymentRecord(invoice,vault.payments,payment,vault.documents);const payments=[...vault.payments];const index=payments.findIndex(item=>item.id===normalized.id);const isNew=index<0;if(index>=0)payments[index]=normalized;else payments.push(normalized);const documentEvents=isNew?[...vault.documentEvents,createDocumentEvent(invoice,'payment-recorded',normalized.reference,undefined,normalized.amount)]:vault.documentEvents;await this.persist({...vault,payments,documentEvents});this.showToast(t('Payment recorded.','تم تسجيل الدفعة.'),'success');};
  private deletePayment=async(payment:PaymentRecord)=>{const vault=this.requireVault();const invoice=vault.documents.find(document=>document.id===payment.invoiceId);const documentEvents=invoice?[...vault.documentEvents,createDocumentEvent(invoice,'payment-deleted',payment.reference,undefined,payment.amount)]:vault.documentEvents;await this.persist({...vault,payments:vault.payments.filter(item=>item.id!==payment.id),documentEvents});this.showToast(t('Payment deleted.','تم حذف الدفعة.'),'success');};
  private saveCustomer=async(customer:Customer)=>{const vault=this.requireVault();const index=vault.customers.findIndex(c=>c.id===customer.id);const customers=[...vault.customers];if(index>=0)customers[index]={...customer,updatedAt:new Date().toISOString()};else customers.push(customer);await this.persist({...vault,customers});};
  private saveSupplier=async(supplier:Supplier)=>{const errors=validateSupplier(supplier);if(errors.length)throw new Error(errors[0]);const vault=this.requireVault();const suppliers=[...vault.suppliers];const index=suppliers.findIndex(item=>item.id===supplier.id);const next={...supplier,defaultCurrency:supplier.defaultCurrency.trim().toUpperCase(),updatedAt:new Date().toISOString()};if(index>=0)suppliers[index]=next;else suppliers.push(next);await this.persist({...vault,suppliers});this.showToast(t('Supplier saved.','تم حفظ المورد.'),'success');};
  private deleteSupplier=async(supplier:Supplier)=>{const vault=this.requireVault();if(vault.expenses.some(expense=>expense.supplierId===supplier.id))throw new Error(t('This supplier is referenced by historical expenses and cannot be deleted.','هذا المورد مرتبط بمصروفات تاريخية ولا يمكن حذفه.'));await this.persist({...vault,suppliers:vault.suppliers.filter(item=>item.id!==supplier.id)});this.showToast(t('Supplier deleted. Historical purchase snapshots were preserved.','تم حذف المورد مع الاحتفاظ بنسخ بياناته داخل المشتريات التاريخية.'),'success');};
  private savePurchaseRecord=async(purchase:PurchaseRecord)=>{const vault=this.requireVault();const existing=vault.purchases.find(item=>item.id===purchase.id);if(existing&&existing.status!=='draft')throw new Error(t('Posted or reversed purchases are read-only.','المشتريات المرحلة أو المعكوسة للقراءة فقط.'));const errors=validatePurchase(purchase,vault.savedItems);if(errors.length)throw new Error(errors[0]);if(vault.purchases.some(item=>item.id!==purchase.id&&item.number.trim().toLowerCase()===purchase.number.trim().toLowerCase()))throw new Error(t('Purchase number already exists.','رقم الشراء مستخدم بالفعل.'));const purchases=[...vault.purchases];const index=purchases.findIndex(item=>item.id===purchase.id);const next={...purchase,status:'draft' as const,currency:purchase.currency.trim().toUpperCase(),updatedAt:new Date().toISOString()};if(index>=0)purchases[index]=next;else purchases.push(next);await this.persist({...vault,purchases});this.showToast(t('Purchase draft saved.','تم حفظ مسودة الشراء.'),'success');};
  private deletePurchaseRecord=async(purchase:PurchaseRecord)=>{const vault=this.requireVault();const current=vault.purchases.find(item=>item.id===purchase.id);if(!current||current.status!=='draft')throw new Error(t('Only draft purchases can be deleted.','يمكن حذف مسودات الشراء فقط.'));if(vault.inventoryMovements.some(movement=>movement.sourceId===purchase.id))throw new Error(t('This purchase already has inventory history and cannot be deleted.','لهذا الشراء سجل مخزون ولا يمكن حذفه.'));await this.persist({...vault,purchases:vault.purchases.filter(item=>item.id!==purchase.id)});this.showToast(t('Purchase draft deleted.','تم حذف مسودة الشراء.'),'success');};
  private postPurchaseRecord=async(purchase:PurchaseRecord)=>{const vault=this.requireVault();const existing=vault.purchases.find(item=>item.id===purchase.id);if(existing&&existing.status!=='draft')throw new Error(t('Purchase is already posted or reversed.','الشراء مرحل أو معكوس بالفعل.'));if(vault.purchases.some(item=>item.id!==purchase.id&&item.number.trim().toLowerCase()===purchase.number.trim().toLowerCase()))throw new Error(t('Purchase number already exists.','رقم الشراء مستخدم بالفعل.'));const result=postPurchase(purchase,vault.savedItems,vault.inventoryMovements);const purchases=[...vault.purchases];const index=purchases.findIndex(item=>item.id===purchase.id);if(index>=0)purchases[index]=result.purchase;else purchases.push(result.purchase);await this.persist({...vault,purchases,inventoryMovements:[...vault.inventoryMovements,...result.movements],savedItems:result.savedItems});this.showToast(t('Purchase posted and inventory received.','تم ترحيل الشراء واستلام المخزون.'),'success');};
  private reversePurchaseRecord=async(purchase:PurchaseRecord,reason:string)=>{const vault=this.requireVault();const current=vault.purchases.find(item=>item.id===purchase.id);if(!current)throw new Error(t('Purchase not found.','عملية الشراء غير موجودة.'));const result=reversePurchase(current,reason,vault.inventoryMovements,vault.savedItems);const purchases=vault.purchases.map(item=>item.id===current.id?result.purchase:item);await this.persist({...vault,purchases,inventoryMovements:[...vault.inventoryMovements,...result.movements],savedItems:result.savedItems});this.showToast(t('Purchase reversed with an audit-preserving stock reversal.','تم عكس الشراء مع الحفاظ على سجل تدقيق وحركة مخزون عكسية.'),'success');};
  private saveExpenseRecord=async(expense:ExpenseRecord)=>{const errors=validateExpense(expense);if(errors.length)throw new Error(errors[0]);const vault=this.requireVault();const expenses=[...vault.expenses];const index=expenses.findIndex(item=>item.id===expense.id);const next={...expense,currency:expense.currency.trim().toUpperCase(),updatedAt:new Date().toISOString()};if(index>=0)expenses[index]=next;else expenses.push(next);await this.persist({...vault,expenses});this.showToast(t('Expense saved.','تم حفظ المصروف.'),'success');};
  private deleteExpenseRecord=async(expense:ExpenseRecord)=>{const vault=this.requireVault();await this.persist({...vault,expenses:vault.expenses.filter(item=>item.id!==expense.id)});this.showToast(t('Expense deleted.','تم حذف المصروف.'),'success');};
  private saveInventoryMovement=async(movement:InventoryMovementRecord)=>{if(!inventoryMovementIsManual(movement))throw new Error(t('Only manual inventory movements can be added here.','يمكن إضافة حركات المخزون اليدوية فقط من هنا.'));const vault=this.requireVault();if(vault.inventoryMovements.some(item=>item.id===movement.id))throw new Error(t('Inventory movement already exists.','حركة المخزون موجودة بالفعل.'));if(!vault.savedItems.some(item=>item.id===movement.itemId))throw new Error(t('Saved item not found.','الصنف المحفوظ غير موجود.'));await this.persist({...vault,inventoryMovements:[...vault.inventoryMovements,movement]});this.showToast(t('Inventory movement recorded.','تم تسجيل حركة المخزون.'),'success');};
  private deleteInventoryMovement=async(movement:InventoryMovementRecord)=>{if(!inventoryMovementIsManual(movement))throw new Error(t('Purchase inventory history must be reversed through the purchase.','يجب عكس سجل مخزون الشراء من عملية الشراء نفسها.'));const vault=this.requireVault();if(vault.inventoryMovements.some(item=>item.sourceId===movement.id&&item.type==='adjustment'))throw new Error(t('This manual movement has already been reversed.','تم عكس هذه الحركة اليدوية مسبقًا.'));const reversal=reverseManualInventoryMovement(movement);await this.persist({...vault,inventoryMovements:[...vault.inventoryMovements,reversal]});this.showToast(t('Manual inventory movement reversed with audit history preserved.','تم عكس حركة المخزون اليدوية مع الاحتفاظ بسجل التدقيق.'),'success');};
  private deleteCustomer=async(customer:Customer)=>{const vault=this.requireVault();await this.persist({...vault,customers:vault.customers.filter(c=>c.id!==customer.id)});this.showToast(t('Customer deleted.','تم حذف العميل.'),'success');};
  private saveCompany=async(company:CompanySettings)=>{const vault=this.requireVault();const smartDefaults={...vault.appSettings.smartDefaults,currency:company.defaultCurrency||'USD',language:company.defaultLanguage,incoterm:company.defaultIncoterm,paymentTerms:company.defaultPaymentTerms,deliveryTime:company.defaultDeliveryTime};const appSettings={...vault.appSettings,smartDefaults};await this.persist({...vault,company,appSettings});await this.syncPublicPreferences(company.logoDataUrl,this.requireVault().appSettings.uiLanguage);};
  private saveAppSettings=async(appSettings:AppSettings)=>{const vault=this.requireVault();const next={...appSettings,uiLanguage:appSettings.uiLanguage??'en'};await this.persist({...vault,appSettings:next});const current=this.requireVault();await this.syncPublicPreferences(current.company.logoDataUrl,current.appSettings.uiLanguage);touchSession();this.resetAutoLock();};
  private changePin=async(currentPin:string,newPin:string)=>{this.editorMustBeClosed('changing the PIN','تغيير رمز PIN');await this.beginProtectedOperation();try{const result=await changePin(currentPin,newPin);await establishSession(result.key);this.vaultWriteTail=Promise.resolve(this.state.vault);this.setState({key:result.key},()=>this.scheduleCloudSync(500));this.showToast(t('PIN changed.','تم تغيير رمز PIN.'),'success');}finally{this.endProtectedOperation();}};
  private backup=async(pin:string)=>{this.editorMustBeClosed('creating a backup','إنشاء نسخة احتياطية');await this.drainVaultWrites();const security=await getSecurity();if(!security)throw new Error(t('Security settings are missing.','إعدادات الأمان غير موجودة.'));await verifyPin(pin,security);await exportBackup(pin,this.requireVault());};
  private restore=async(file:File,pin:string)=>{this.editorMustBeClosed('restoring a backup','استعادة نسخة احتياطية');const restored=this.normalizedVault(await readBackup(file,pin));await this.beginProtectedOperation();try{const key=this.state.key;if(!key)throw new Error(t('App is locked.','التطبيق مقفل.'));const vault=await restoreVaultWithCurrentKey(key,restored);this.vaultWriteTail=Promise.resolve(vault);await this.syncPublicPreferences(vault.company.logoDataUrl,vault.appSettings.uiLanguage);touchSession();await new Promise<void>(resolve=>this.setState({vault,screen:'documents',editorDoc:null},resolve));this.resetAutoLock();}finally{this.endProtectedOperation();this.scheduleCloudSync(500);}};
  private requireVault():VaultPayload{if(!this.state.vault)throw new Error(t('App is locked.','التطبيق مقفل.'));return this.state.vault;}
  private waitForPrintAssets=async()=>{await new Promise<void>(resolve=>window.requestAnimationFrame(()=>window.requestAnimationFrame(()=>resolve())));try{if(document.fonts)await document.fonts.ready;}catch{}const images=Array.from(document.querySelectorAll<HTMLImageElement>('.print-portal img'));await Promise.all(images.map(async image=>{if(image.complete&&image.naturalWidth>0)return;try{if(typeof image.decode==='function'){await image.decode();return;}}catch{}await new Promise<void>(resolve=>{const done=()=>resolve();image.addEventListener('load',done,{once:true});image.addEventListener('error',done,{once:true});window.setTimeout(done,1200);});}));};
  private launchPrint=async()=>{await this.waitForPrintAssets();if(!this.state.printDoc)return;window.print();};
  private requestPrint=async(doc:LourexDocument,mode:'print'|'pdf'|'share'):Promise<void>=>{try{const errors=validateDocument(doc);if(Object.keys(errors).length)throw new Error(t('Complete the required document fields before printing or sharing.','أكمل الحقول المطلوبة قبل الطباعة أو المشاركة.'));const vault=this.requireVault();if(vault.documents.some(d=>d.id!==doc.id&&d.number.trim().toLowerCase()===doc.number.trim().toLowerCase()))throw new Error(t('Document number already exists.','رقم المستند مستخدم بالفعل.'));let target:LourexDocument;const existing=vault.documents.find(d=>d.id===doc.id);if(doc.status==='final'&&existing?.status==='final')target=structuredClone(doc);else{target={...structuredClone(doc),status:'final',updatedAt:new Date().toISOString()};await this.saveDocument(target,false);target=structuredClone(this.requireVault().documents.find(saved=>saved.id===target.id)??target);}const customer=target.customerSnapshot?.companyNameEn||target.customerSnapshot?.companyNameAr||'Customer';const prefix=`LOUREX-${safeFilename(target.number)}-${safeFilename(customer)}`;document.title=prefix;await new Promise<void>((resolve,reject)=>this.setState({printDoc:target},()=>{document.body.classList.add('printing');void this.launchPrint().then(resolve,reject);}));}catch(e){const message=e instanceof Error?e.message:t('Unable to prepare document.','تعذر تجهيز المستند.');try{(window as any).__LOUREX_OUTPUT_ERROR__?.(message);}catch{}this.showToast(message,'error');throw e;}};
  private afterPrint=()=>{document.body.classList.remove('printing');document.title='LOUREX Invoice';this.setState({printDoc:null});};
  private closeEditor=()=>{this.setState({screen:'documents',editorDoc:null});};
  private cloudModal=()=> <CloudAccountModal open={this.state.cloudModal} user={this.state.cloudUser} syncState={this.state.cloudSyncState} syncMessage={this.state.cloudSyncMessage} onClose={()=>this.setState({cloudModal:false})} onSignIn={this.cloudSignIn} onCreate={this.cloudCreate} onReset={this.cloudReset} onSync={this.cloudSyncNow} onSignOut={this.cloudSignOut}/>;
  private authCloudShell=(content:any)=> <div className="auth-shell">{content}<div className={`auth-cloud-launcher cloud-${this.state.cloudSyncState}`}><Button icon="backup" onClick={()=>this.setState({cloudModal:true})}>{this.state.cloudUser?t('Cloud Account','الحساب السحابي'):t('Cloud Sign In','الدخول السحابي')}</Button></div>{this.cloudModal()}</div>;
  private cloudHeaderLabel=()=>this.state.cloudSyncState==='syncing'?t('Syncing','مزامنة'):this.state.cloudSyncState==='queued'?t('Saved','محفوظ'):this.state.cloudSyncState==='offline'?t('Offline','غير متصل'):this.state.cloudSyncState==='error'?t('Retry','إعادة'):this.state.cloudSyncState==='synced'?t('Synced','متزامن'):t('Cloud','السحابة');

  render():any{
    const activeLanguage=this.state.vault?.appSettings.uiLanguage??this.state.uiLanguage;setUiLanguage(activeLanguage);
    if(this.state.loading)return <div className="loading-screen"><Brand logoDataUrl={this.state.publicLogo} language={activeLanguage}/><span className="loading-line"/></div>;
    if(this.state.firstRun)return this.authCloudShell(<AuthScreenSelector mode="setup" company={defaultCompany()} logoDataUrl={this.state.publicLogo} language={activeLanguage} onLanguageChange={this.changePublicLanguage} onFinish={this.finishSetup}/>);
    if(!this.state.unlocked)return this.authCloudShell(<AuthScreenSelector mode="unlock" logoDataUrl={this.state.publicLogo} language={activeLanguage} onLanguageChange={this.changePublicLanguage} onUnlock={this.unlock}/>);
    const vault=this.requireVault();
    return <div className="app-root"><div className="app-ui"><header className="app-header"><button className="header-brand" disabled={this.state.screen==='editor'} onClick={()=>this.setState({screen:'documents',editorDoc:null})}><Brand compact logoDataUrl={vault.company.logoDataUrl} language={activeLanguage}/></button>{this.state.screen!=='editor'?<nav className="main-nav"><button className={this.state.screen==='documents'?'active':''} aria-current={this.state.screen==='documents'?'page':undefined} onClick={()=>this.setState({screen:'documents',editorDoc:null})}><Icon name="file"/>{t('Documents','المستندات')}</button><button className={this.state.screen==='customers'?'active':''} aria-current={this.state.screen==='customers'?'page':undefined} onClick={()=>this.setState({screen:'customers',editorDoc:null})}><Icon name="users"/>{t('Customers','العملاء')}</button><button className={this.state.screen==='receivables'?'active':''} aria-current={this.state.screen==='receivables'?'page':undefined} onClick={()=>this.setState({screen:'receivables',editorDoc:null})}><Icon name="invoice"/>{t('Receivables','المستحقات')}</button><button className={this.state.screen==='reports'?'active':''} aria-current={this.state.screen==='reports'?'page':undefined} onClick={()=>this.setState({screen:'reports',editorDoc:null})}><Icon name="file"/>{t('Reports','التقارير')}</button><button className={this.state.screen==='items'?'active':''} aria-current={this.state.screen==='items'?'page':undefined} onClick={()=>this.setState({screen:'items',editorDoc:null})}><Icon name="items"/>{t('Items','الأصناف')}</button><button className={this.state.screen==='operations'?'active':''} aria-current={this.state.screen==='operations'?'page':undefined} onClick={()=>this.setState({screen:'operations',editorDoc:null})}><Icon name="invoice"/>{t('Operations','العمليات')}</button></nav>:<div className="header-editor-context">{t('Document Editor','محرر المستند')}</div>}<div className="header-actions">{this.state.screen!=='editor'?<div className="new-doc-menu"><Button icon="plus" variant="primary" onClick={()=>this.setState({newMenu:!this.state.newMenu})}>{t('New Document','مستند جديد')}</Button>{this.state.newMenu?<div className="new-menu"><button onClick={()=>void this.newDocument('proforma')}><Icon name="proforma"/><span><strong>{t('Proforma Invoice','عرض سعر')}</strong><small>{t('Commercial quotation','عرض تجاري')}</small></span></button><button onClick={()=>void this.newDocument('invoice')}><Icon name="invoice"/><span><strong>{t('Invoice','فاتورة')}</strong><small>{t('Final invoice','فاتورة نهائية')}</small></span></button></div>:null}</div>:null}<Button icon="backup" title={this.state.cloudSyncMessage||this.cloudHeaderLabel()} className={`cloud-header-button cloud-${this.state.cloudSyncState}`} onClick={()=>this.setState({cloudModal:true})}>{this.cloudHeaderLabel()}</Button>{this.state.screen!=='editor'?<IconButton icon="lock" className="header-lock-button" label={t('Lock App','قفل التطبيق')} onClick={this.lock}/>:null}<IconButton icon="settings" label={t('Settings','الإعدادات')} onClick={()=>this.setState({settingsOpen:true})}/></div></header>
      <main className={this.state.screen==='editor'?'editor-main':'main-content'}>{this.state.screen==='documents'?<DocumentsPage documents={vault.documents} payments={vault.payments} onNew={(k)=>void this.newDocument(k)} onOpen={(d)=>void this.openDocument(d)} onDuplicate={(d)=>void this.duplicate(d)} onPrint={this.requestPrint} onDelete={(d)=>this.setState({deletingDoc:d})}/>:null}{this.state.screen==='customers'?<CustomersPage customers={vault.customers} company={vault.company} onSave={this.saveCustomer} onDelete={this.deleteCustomer} onNewDocument={this.newDocumentForCustomer}/>:null}{this.state.screen==='receivables'?<ReceivablesPage customers={vault.customers} documents={vault.documents} payments={vault.payments} company={vault.company}/>:null}{this.state.screen==='reports'?<ReportsPage company={vault.company} customers={vault.customers} documents={vault.documents} payments={vault.payments}/>:null}{this.state.screen==='items'?<SavedItemsPage items={vault.savedItems} currency={vault.appSettings.smartDefaults.currency||vault.company.defaultCurrency||'USD'} onSave={this.saveSavedItem} onSaveMany={this.saveSavedItemsBatch} onDelete={this.deleteSavedItem}/>:null}{this.state.screen==='operations'?<OperationsPage suppliers={vault.suppliers} purchases={vault.purchases} expenses={vault.expenses} inventoryMovements={vault.inventoryMovements} items={vault.savedItems} defaultCurrency={vault.appSettings.smartDefaults.currency||vault.company.defaultCurrency||'USD'} onSaveSupplier={this.saveSupplier} onDeleteSupplier={this.deleteSupplier} onSavePurchase={this.savePurchaseRecord} onDeletePurchase={this.deletePurchaseRecord} onPostPurchase={this.postPurchaseRecord} onReversePurchase={this.reversePurchaseRecord} onSaveExpense={this.saveExpenseRecord} onDeleteExpense={this.deleteExpenseRecord} onSaveInventoryMovement={this.saveInventoryMovement} onDeleteInventoryMovement={this.deleteInventoryMovement}/>:null}{this.state.screen==='editor'&&this.state.editorDoc?<EditorPage document={this.state.editorDoc} documents={vault.documents} customers={vault.customers} company={vault.company} savedItems={vault.savedItems} payments={vault.payments} documentEvents={vault.documentEvents} documentRevisions={vault.documentRevisions} smartDefaults={vault.appSettings.smartDefaults} onClose={this.closeEditor} onSave={this.saveDocument} onSaveCustomer={this.saveCustomer} onSaveSavedItem={this.saveSavedItem} onSaveDocumentItem={this.saveDocumentItem} onUseSavedItems={this.useSavedItems} onDeleteSavedItem={this.deleteSavedItem} onSaveSmartDefaults={this.saveSmartDefaults} onSavePayment={this.savePayment} onDeletePayment={this.deletePayment} onBeginRevision={this.beginRevision} onDiscardRevision={this.discardRevision} onVoidDocument={this.voidDocument} onCreateCreditNote={this.createCreditNote} onConvert={this.convert} onPrint={this.requestPrint}/>:null}</main>
      <SettingsModal open={this.state.settingsOpen} company={vault.company} appSettings={vault.appSettings} onClose={()=>this.setState({settingsOpen:false})} onSaveCompany={this.saveCompany} onSaveAppSettings={this.saveAppSettings} onChangePin={this.changePin} onLock={this.lock} onBackup={this.backup} onRestore={this.restore}/>
      {this.cloudModal()}
      <ConfirmDialog open={Boolean(this.state.deletingDoc)} title={t(`Delete ${this.state.deletingDoc?.number ?? 'document'}?`,`حذف ${this.state.deletingDoc?.number ?? 'المستند'}؟`)} message={t('This action cannot be undone.','لا يمكن التراجع عن هذا الإجراء.')} onCancel={()=>this.setState({deletingDoc:null})} onConfirm={()=>void this.deleteDocument()}/><Toast text={this.state.toast} tone={this.state.toastTone}/></div>
      <div className="print-portal">{this.state.printDoc?<TemplateRenderer document={this.state.printDoc} scale={1}/>:null}</div></div>;
  }
}
